("T35", False, "For each module presentation, the number of students with at least one late submission. Return module_presentation and count.",
 "SELECT p.module_presentation, COUNT(DISTINCT s.enrollment_key) FROM fact_assessment_submission s JOIN dim_presentation p USING (presentation_key) WHERE s.is_late=1 GROUP BY p.module_presentation"),
